<template>
  <div class="external-page">
    <el-form :model="query" inline class="query-form"><el-form-item label="外管账号"><el-input v-model="query.loginName" clearable/></el-form-item><el-form-item label="关联Woha ID"><el-input v-model="query.wohaChatNo" clearable/></el-form-item><el-form-item label="角色"><el-select v-model="query.roleCode" clearable><el-option v-for="item in roles" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="resetQuery">重置</el-button></el-form>
    <div class="table-toolbar"><span class="section-title">外管账号</span><el-button type="primary" @click="openCreate">开通外管</el-button></div>
    <el-table v-loading="loading" :data="rows" border style="margin-top:16px"><el-table-column prop="loginName" label="外管" min-width="130"/><el-table-column prop="wohaChatNo" label="关联Woha ID" min-width="130"/><el-table-column label="角色" min-width="100"><template #default="{row}">{{ roleName(row.roleCode) }}</template></el-table-column><el-table-column label="功能权限" align="center"><template #default="{row}">{{ permissionCount(row.permissions) }}项</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status === '0' ? 'success' : 'info'">{{ row.status === '0' ? '正常' : '停用' }}</el-tag></template></el-table-column><el-table-column prop="createTime" label="开通时间" min-width="165"/><el-table-column label="操作" width="270" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button link type="primary" @click="openResetPassword(row)">重置密码</el-button><el-button link :type="row.status === '0' ? 'warning' : 'success'" @click="toggleStatus(row)">{{ row.status === '0' ? '停用' : '启用' }}</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
    <pagination v-show="total > 0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="load"/>
    <el-dialog v-model="visible" :title="form.id ? '编辑外管账号' : '开通外管'" width="820px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-width="130px"><el-form-item label="登录账号" prop="loginName"><el-input v-model="form.loginName" :disabled="Boolean(form.id)"/></el-form-item><el-form-item :label="form.id ? '新密码' : '登录密码'" prop="password"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-form-item label="姓名" prop="realName"><el-input v-model="form.realName"/></el-form-item><el-form-item label="关联Woha ID" prop="wohaChatNo"><el-input v-model.number="form.wohaChatNo"/></el-form-item><el-form-item label="角色" prop="roleCode"><el-select v-model="form.roleCode"><el-option v-for="item in roles" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item v-if="form.roleCode !== 'SUPER_ADMIN'" label="上级账号ID"><el-input v-model.number="form.parentId"/></el-form-item><el-form-item label="所属大区" prop="regionId"><el-select v-model="form.regionId"><el-option v-for="item in regions" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="功能权限"><el-checkbox-group v-model="form.permissions"><el-checkbox v-for="item in permissions" :key="item.value" :label="item.value">{{ item.label }}</el-checkbox></el-checkbox-group></el-form-item></el-form>
      <el-divider>礼包额度</el-divider><el-table :data="form.giftQuotas" border size="small"><el-table-column prop="giftName" label="礼包"/><el-table-column label="可赠份数" width="160"><template #default="{row}"><el-input-number v-model="row.quotaCount" :min="0"/></template></el-table-column><el-table-column prop="usedCount" label="已用" width="90"/><el-table-column prop="receiveLimit" label="每人限领" width="110"/></el-table>
      <template v-if="form.id"><el-divider>靓号号池</el-divider><div class="pool-add"><el-input v-model.number="poolChatNo" placeholder="输入靓号"/><el-button type="primary" @click="addPool">划拨</el-button></div><el-table :data="chatNos" border size="small" max-height="200"><el-table-column prop="chatNo" label="靓号"/><el-table-column label="状态"><template #default="{row}">{{ row.status === '0' ? '可用' : '已分配' }}</template></el-table-column><el-table-column prop="receiverUid" label="接收用户UID"/><el-table-column prop="expireTime" label="到期时间"/><el-table-column label="操作" width="80"><template #default="{row}"><el-button v-if="row.status === '0'" link type="danger" @click="removePool(row)">回收</el-button></template></el-table-column></el-table></template>
      <template #footer><el-button @click="visible = false">取消</el-button><el-button type="primary" @click="submit">保存</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { ElMessage, ElMessageBox } from 'element-plus'
import { addExternalAccount, addExternalAccountChatNo, changeExternalAccountStatus, delExternalAccount, delExternalAccountChatNo, getExternalAccount, listExternalAccount, listExternalAccountChatNos, listExternalGiftPackQuotas, listExternalGiftPacks, resetExternalAccountPassword, updateExternalAccount } from '@/api/external/manager'
const roles = [{ value: 'SUPER_ADMIN', label: 'Super Admin' }, { value: 'BD_LEADER', label: 'BD Leader' }, { value: 'BD', label: 'BD' }]
const regions = [{ value: 1, label: '全球' }, { value: 2, label: '东南亚' }, { value: 3, label: '华语' }, { value: 4, label: '中东' }, { value: 5, label: '印度' }, { value: 6, label: '越南' }, { value: 7, label: '菲律宾' }]
const permissions = [{ value: 'VIEW_TEAM_GUILD', label: '查看团队与公会' }, { value: 'VIEW_GUILD_FLOW', label: '查看公会流水' }, { value: 'CREATE_SUBORDINATE', label: '新增下级' }, { value: 'CREATE_GUILD', label: '新建公会' }, { value: 'SEND_GIFT_PACK', label: '赠送礼包' }, { value: 'ASSIGN_CHAT_NO', label: '分配靓号' }, { value: 'EXECUTE_BAN', label: '执行封禁' }, { value: 'SUBMIT_REPORT', label: '提交举报' }, { value: 'EXPORT_GUILD_LIST', label: '导出公会列表' }, { value: 'EXPORT_GUILD_FLOW', label: '导出公会流水' }, { value: 'EXPORT_TEAM_MEMBER', label: '导出团队成员' }, { value: 'EXPORT_GIFT_ISSUE', label: '导出礼包赠送记录' }, { value: 'EXPORT_ACCOUNT_ASSIGNMENT', label: '导出账号分配记录' }]
const loading = ref(false); const rows = ref([]); const total = ref(0); const visible = ref(false); const formRef = ref(); const giftPacks = ref([]); const chatNos = ref([]); const poolChatNo = ref(); const query = reactive({ pageNum: 1, pageSize: 10, loginName: '', wohaChatNo: undefined, roleCode: undefined }); const form = reactive({})
const rules = { loginName: [{ required: true, message: '请输入登录账号', trigger: 'blur' }], password: [{ validator: (_, value, callback) => { if (!form.id && !value) callback(new Error('请输入登录密码')); else if (value && !/^(?=.*[A-Za-z])(?=.*\d).{8,50}$/.test(value)) callback(new Error('密码至少8位且包含字母和数字')); else callback() }, trigger: 'blur' }], realName: [{ required: true, message: '请输入姓名', trigger: 'blur' }], wohaChatNo: [{ required: true, message: '请输入Woha ID', trigger: 'blur' }], roleCode: [{ required: true, message: '请选择角色', trigger: 'change' }], regionId: [{ required: true, message: '请选择大区', trigger: 'change' }] }
const roleName = value => roles.find(item => item.value === value)?.label || value; const permissionCount = value => value ? value.split(',').filter(Boolean).length : 0
function buildQuotas(saved = []) { const savedMap = new Map(saved.map(item => [item.giftId, item])); return giftPacks.value.filter(item => item.status === '0').map(item => ({ giftId: item.id, giftName: item.giftName, receiveLimit: item.receiveLimit, quotaCount: savedMap.get(item.id)?.quotaCount || 0, usedCount: savedMap.get(item.id)?.usedCount || 0 })) }
async function load() { loading.value = true; try { const data = await listExternalAccount(query); rows.value = data.rows; total.value = data.total } finally { loading.value = false } }
function resetQuery() { Object.assign(query, { pageNum: 1, loginName: '', wohaChatNo: undefined, roleCode: undefined }); load() }
async function openCreate() { Object.assign(form, { id: null, loginName: '', password: '', realName: '', wohaChatNo: undefined, roleCode: 'BD', parentId: undefined, regionId: 2, permissions: [], giftQuotas: buildQuotas() }); chatNos.value = []; visible.value = true; await nextTick(); formRef.value?.clearValidate() }
async function openEdit(row) { const [accountRes, quotaRes, chatNoRes] = await Promise.all([getExternalAccount(row.id), listExternalGiftPackQuotas({ accountId: row.id }), listExternalAccountChatNos(row.id)]); Object.assign(form, accountRes.data, { password: '', permissions: accountRes.data.permissions ? accountRes.data.permissions.split(',').filter(Boolean) : [], giftQuotas: buildQuotas(quotaRes.data) }); chatNos.value = chatNoRes.data; poolChatNo.value = undefined; visible.value = true; await nextTick(); formRef.value?.clearValidate() }
function submit() { formRef.value.validate(async valid => { if (!valid) return; const data = { ...form, giftQuotas: form.giftQuotas.map(item => ({ giftId: item.giftId, quotaCount: item.quotaCount })) }; if (data.id && !data.password) delete data.password; if (data.id) await updateExternalAccount(data.id, data); else await addExternalAccount(data); ElMessage.success('保存成功'); visible.value = false; load() }) }
async function addPool() { if (!poolChatNo.value) return ElMessage.warning('请输入靓号'); await addExternalAccountChatNo({ accountId: form.id, chatNo: poolChatNo.value }); const response = await listExternalAccountChatNos(form.id); chatNos.value = response.data; poolChatNo.value = undefined; ElMessage.success('划拨成功') }
async function removePool(row) { await ElMessageBox.confirm(`确认回收靓号 ${row.chatNo}？`, '提示', { type: 'warning' }); await delExternalAccountChatNo(form.id, row.chatNo); const response = await listExternalAccountChatNos(form.id); chatNos.value = response.data }
async function toggleStatus(row) { await changeExternalAccountStatus(row.id, row.status === '0' ? '1' : '0'); load() }
async function remove(row) { await ElMessageBox.confirm(`确认删除外管账号 ${row.loginName}？`, '提示', { type: 'warning' }); await delExternalAccount(row.id); load() }
async function openResetPassword(row) { const { value } = await ElMessageBox.prompt('请输入新密码，至少8位且包含字母和数字', `重置${row.loginName}的密码`, { inputType: 'password' }); await resetExternalAccountPassword(row.id, value); ElMessage.success('重置成功') }
async function init() { const response = await listExternalGiftPacks(); giftPacks.value = response.data; await load() }
init()
</script>
<style scoped>.external-page{box-sizing:border-box;padding:20px}.query-form{margin-bottom:12px}.table-toolbar{display:flex;align-items:center;justify-content:space-between}.section-title{font-size:16px;font-weight:600}.pool-add{display:flex;gap:8px;margin-bottom:12px}.pool-add .el-input{max-width:220px}</style>
